import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Myerson–Satterthwaite","description":"","frontmatter":{"title":"Myerson–Satterthwaite","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/myerson-satterthwaite.md","filePath":"econ/myerson-satterthwaite.md","lastUpdated":1789023840000}'),E={name:"econ/myerson-satterthwaite.md"};function p(m,a,A,u,_,B){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="myerson–satterthwaite" tabindex="-1">Myerson–Satterthwaite <a class="header-anchor" href="#myerson–satterthwaite" aria-label="Permalink to &quot;Myerson–Satterthwaite&quot;">​</a></h1><div class="epigraph"><p>买卖双方估值的支撑若重叠，不存在既激励相容、又事中个人理性、又预算平衡、又事后有效的交易机制。</p><footer>—— Myerson and Satterthwaite, Efficient Mechanisms for Bilateral Trading, Journal of Economic Theory, 1983</footer></div><p><a href="/econ/double-auction">上一课</a>在 \\(k\\) 双拍卖里看到遮挡与不成交。缺口是：换一套更弯的规则——抽签、补贴、多轮便宜话——能否把成交集扩回 \\(\\{v\\ge c\\}\\)，同时不强迫人参与、不额外贴钱？Myerson–Satterthwaite 说不能。本课钉这条不可能，不把期望外部性机制提前写成解法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一人买家、一人卖家，类型独立，密度在 \\([\\underline v,\\bar v]\\times[\\underline c,\\bar c]\\) 上严格为正且支撑重叠：存在正概率 \\(v\\gt c\\) 与正概率 \\(v\\lt c\\)。准线性，风险中性。机制：报告类型（显示原理），以概率 \\(q(\\hat v,\\hat c)\\) 成交、转移 \\(t\\)。要求：</p><ul><li>事后有效：\\(q=1\\) 当且仅当 \\(v\\ge c\\)（平局可任意）；</li><li>贝叶斯激励相容；</li><li>事中个人理性：每一类型的期望支付不低于不参与（买家 \\(0\\)，卖家保留 \\(c\\) 的期望）；</li><li>预算平衡：买家付出等于卖家收到（或弱平衡：设计者不亏钱）。</li></ul><p>四条不能同时成立。双拍卖的无效率不是线性猜错，是可行集为空。</p><h3 id="重叠支撑是关键" tabindex="-1">重叠支撑是关键 <a class="header-anchor" href="#重叠支撑是关键" aria-label="Permalink to &quot;重叠支撑是关键&quot;">​</a></h3><p>若几乎肯定 \\(v\\gt c\\)（例如买家支撑整体高于卖家），有效交易「总能成交」，租金问题轻，可能存在有效机制。重叠意味着必须靠报告来分辨该不该成交，IC 要留给边际类型租金，IR 不让设计者从两端抽干，预算又不允许外面贴钱——三头不够。</p><p><span class="marginnote">证明走包络：有效 \\(q\\) 钉死期望租金，事中 IR 要求最低买家与最高卖家租金不少于零，于是期望转移出现缺口：买家付不出卖家必须拿到的那笔。显示原理保证：间接机制若能做到，直接机制也能；故间接也救不了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：独立连续密度、重叠支撑、准线性。用<a href="/econ/revelation-principle">显示原理</a>收成直接机制。有效配置代入包络，算期望社会剩余与必须留给代理人的信息租金之差，证明设计者的期望利润为负。对照：VCG / 枢轴能有效且占优策略 IC，但预算赤字；补贴来自机制外。</p>',12)),(e(),s(d,null,{default:r(()=>[c(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20KDA%5B%22k%20%E5%8F%8C%E6%8B%8D%E5%8D%96%EF%BC%9A%E9%81%AE%E6%8C%A1%22%5D%20--%3E%20Q%5B%22%E6%98%AF%E5%90%A6%E6%8D%A2%E8%A7%84%E5%88%99%E5%8F%AF%E6%9C%89%E6%95%88%22%5D%0A%20%20Q%20--%3E%20MS%5B%22IC%20%2B%20%E4%BA%8B%E4%B8%AD%20IR%20%2B%20BB%20%2B%20%E6%9C%89%E6%95%88%22%5D%0A%20%20MS%20--%3E%20EMPTY%5B%22%E9%87%8D%E5%8F%A0%E6%94%AF%E6%92%91%EF%BC%9A%E5%8F%AF%E8%A1%8C%E9%9B%86%E7%A9%BA%22%5D%0A%20%20EMPTY%20--%3E%20AGV%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%94%BE%E6%9D%BE%20IR%EF%BC%8C%E6%9C%9F%E6%9C%9B%E5%A4%96%E9%83%A8%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不可能是可行集空，不是「还没找到聪明规则」。设计者只能选放松哪一条：扭曲 \\(q\\)、贴钱、强迫参与，或假定类型公开。</p><p>弱化任一条即可逃离：放弃事后有效（双拍卖、最优机制扭曲 \\(q\\)）；放弃事中 IR（强迫参与或抽事前保证金）；放弃 BB（计划者贴钱）；放弃 IC（假定类型公开）。事前收一笔入场费再退还，有时能把事中 IR 改写成事前 IR，等价于走 AGV 那一支——下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效交易的社会剩余是 \\(\\mathbb{E}[(v-c)_+]\\)。IC 把每个类型的租金写成赢率（成交概率）的积分。事中 IR 卡住两端：最低买家、最高卖家必须至少不亏。这两端恰好是「最没有交易可敲」的人，他们的零租金要求，经过包络传导，变成对中间类型的转移下限。预算平衡要求转移内部抵消，于是出现亏空——与 VCG 公共品赤字是表亲。</p><p>因此「互利一定能谈成」在私型下不成立。科斯定理若读成「只要能谈判、无交易成本就有效」，缺的正是这组 IC+IR+BB。完全信息讨价还价可以有效；不完全信息加上自愿参与，不能。</p><h3 id="与双边垄断不是同一句话" tabindex="-1">与双边垄断不是同一句话 <a class="header-anchor" href="#与双边垄断不是同一句话" aria-label="Permalink to &quot;与双边垄断不是同一句话&quot;">​</a></h3><p>完全信息双边垄断的无效率来自定价（哪一边设价）。MS 即使允许任意随机机制，只要类型隐藏，事后有效仍不可及。无效率的来源是信息，不是「只有两个人所以市场厚不起来」单独一句——虽然两人使 IR 更紧。</p><p><span class="marginnote">Myerson 最优拍卖是一边的机制设计：卖方不要求对每一类型都 IR 到「留下物品的机会成本」那种双边对称。MS 是真正的双边，两边都要请进来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>共同先验、独立、准线性都是条件。关联、多买家多卖家（市场变厚）、类型离散且不重叠，结论可松。实验与中介若能改变 IR（入场费事前收），等于走了放松事中 IR 的那一支。</p><p>后课默认：双边交易在重叠支撑下，不能四者兼得。下一课 AGV 用期望外部性保住有效、IC 与预算平衡，代价是事中 IR。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双拍卖的不成交不能靠更弯的规则消掉。</li><li>重叠支撑下，IC、事中 IR、预算平衡、事后有效不可兼得。</li><li>VCG 有效但不平衡；贴钱或强迫参与才能逃出。</li><li>不完全信息下的科斯「总能谈成」不成立。</li><li>出处：Myerson and Satterthwaite, <em>JET</em>, 1983。</li></ul>',13))])}const I=o(E,[["render",p]]);export{f as __pageData,I as default};
